import random, time, uuid
import requests

RETRYABLE = {429, 502, 503, 504}

def create_payment(payload, max_attempts=5):
    key = str(uuid.uuid4())                    # ONE key for every attempt
    for attempt in range(max_attempts):
        try:
            r = requests.post(
                "https://api.example.com/v1/payments",
                json=payload,                      # sets Content-Type: application/json
                headers={"Idempotency-Key": key},
                timeout=10,                        # never wait forever
            )
        except (requests.Timeout, requests.ConnectionError):
            r = None                               # outcome unknown: retry with the same key
        if r is not None and r.status_code not in RETRYABLE:
            r.raise_for_status()                   # other 4xx/5xx: raise, do not retry
            return r.json()
        retry_after = r.headers.get("Retry-After") if r is not None else None
        wait = float(retry_after) if retry_after else min(30, 2 ** attempt)
        time.sleep(wait + random.uniform(0, 1))    # backoff plus jitter
    raise RuntimeError("payment API still unavailable, giving up")

