  }
  return res.json()                              // a promise; callers await it
}

async function createOrder(order, token) {
  const res = await fetch(`${API}/orders`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
    body: JSON.stringify(order)                  // fetch will not serialize objects
  })
  if (res.status === 422) return { fieldErrors: (await res.json()).errors }
  if (!res.ok) throw new Error(`POST order failed: ${res.status}`)
  return { order: await res.json() }
}

